es:{dashboard:'Panel general',inventory:'Stock e inventario',conversations:'Conversaciones',opportunities:'Oportunidades',contacts:'Contactos',calendar:'Calendario',tasks:'Tareas',ai:'IA conversacional',automation:'Automatizaciones',campaigns:'Campañas',settings:'Configuración',reviews:'Reputación',reports:'Reportes',integrations:'Integraciones',hello:'Bienvenido',lead:'Contactos',pipelineValue:'En negociación',won:'Ventas ganadas',pending:'Tareas pendientes',name:'Nombre',email:'Correo',password:'Contraseña',login:'Iniciar sesión',logout:'Cerrar sesión',newContact:'Nuevo contacto',newDeal:'Nueva oportunidad',newTask:'Nueva tarea',newAppointment:'Nueva cita',phone:'Teléfono',source:'Origen',tags:'Etiquetas',notes:'Notas',save:'Guardar',cancel:'Cancelar',contact:'Contacto',value:'Valor',title:'Título',stage:'Etapa',pipeline:'Embudo',due:'Vencimiento',start:'Inicio',end:'Fin',empty:'No hay registros',internal:'Nota interna',unread:'No leídas',recent:'Recientes',newPipeline:'Nuevo embudo',users:'Usuarios',newUser:'Nuevo usuario',role:'Rol',pendingFeature:'Integración pendiente: se requieren credenciales y configuración del proveedor.',loss:'Motivo de pérdida'},
