function Content({page,t,user,reload,error,kanbanContact,onContactToKanban,permissions}){if(user?.role==='owner')permissions=Object.fromEntries(permissionModuleKeys.map(k=>[k,{view:true,create:true,edit:true,delete:true}]));if(user?.role!=='owner'&&permissions?.[page]?.view!==true)return <div className="panel" role="status">Sin acceso a este módulo. Solicitá permisos al administrador.</div>;switch(page){case'dashboard':return <Dashboard t={t} error={error}/>;case'inventory':return <InventoryPage lang={localStorage.getItem('crm_lang')||'pt'} user={user}/>;case'contacts':return <Contacts t={t} error={error} reload={reload} onContactToKanban={onContactToKanban} permissions={permissions?.contacts} opportunityPermissions={permissions?.opportunities} user={user}/>;case'opportunities':return <Opportunities t={t} error={error} reload={reload} kanbanContact={kanbanContact} permissions={permissions?.opportunities}/>;case'conversations':return <Conversations t={t} error={error} reload={reload} user={user} permissions={permissions?.conversations}/>;case'tasks':return <Tasks t={t} error={error} reload={reload} permissions={permissions?.tasks}/>;case'calendar':return <Calendar t={t} error={error} reload={reload} permissions={permissions?.calendar}/>;case'settings':return <SettingsPage t={t} error={error} user={user} reload={reload}/>;default:return <div className="future"><Bot size={46}/><h2>{t[page]}</h2><p>{t.pendingFeature}</p></div>}}
